"""Ubah HTML menjadi data. Tidak ada jaringan, berkas, atau database di sini."""

import re
from decimal import Decimal, InvalidOperation
from urllib.parse import urljoin

from bs4 import BeautifulSoup

RATING = {"One": 1, "Two": 2, "Three": 3, "Four": 4, "Five": 5}


def parse_harga(teks: str) -> Decimal:
    """'£51.77' -> Decimal('51.77'). Buang semua selain angka dan titik."""
    bersih = re.sub(r"[^0-9.]", "", teks)
    try:
        return Decimal(bersih)
    except InvalidOperation:
        raise ValueError(f"Harga tidak dikenali: {teks!r}") from None


def parse_stok(teks: str) -> int:
    """'In stock (22 available)' -> 22. 'Out of stock' -> 0."""
    cocok = re.search(r"\((\d+) available\)", teks)
    return int(cocok.group(1)) if cocok else 0


def parse_daftar(html: str, url: str) -> tuple[list[str], str | None]:
    """Halaman katalog -> (URL absolut detail buku, URL halaman berikutnya atau None)."""
    sup = BeautifulSoup(html, "html.parser")
    tautan = [urljoin(url, a["href"]) for a in sup.select("article.product_pod h3 a")]
    berikut = sup.select_one("ul.pager li.next a")
    return tautan, urljoin(url, berikut["href"]) if berikut else None


def parse_buku(html: str, url: str) -> dict:
    """Halaman detail -> dict siap disimpan."""
    sup = BeautifulSoup(html, "html.parser")
    utama = sup.select_one("div.product_main")
    if utama is None:
        raise ValueError(f"Bukan halaman buku: {url}")
    tabel = {
        tr.th.get_text(strip=True): tr.td.get_text(strip=True)
        for tr in sup.select("table.table-striped tr")
    }
    kelas_rating = sup.select_one("p.star-rating")["class"]
    return {
        "upc": tabel["UPC"],
        "judul": utama.h1.get_text(strip=True),
        "harga": parse_harga(tabel["Price (incl. tax)"]),
        "stok": parse_stok(tabel["Availability"]),
        "rating": next(RATING[k] for k in kelas_rating if k in RATING),
        "kategori": sup.select("ul.breadcrumb li")[2].get_text(strip=True),
        "url": url,
    }

"""Ambil halaman dengan sopan: robots.txt, jeda, User-Agent, timeout, retry, cache."""

import hashlib
import logging
import time
from pathlib import Path
from urllib.parse import urljoin
from urllib.robotparser import RobotFileParser

import httpx

# Ganti USERNAME dengan username GitHub-mu: pemilik situs bisa melihat siapa yang berkunjung.
REPO = "https://github.com/USERNAME/scraper-harga-buku"
USER_AGENT = f"scraper-buku/0.1 (proyek belajar; +{REPO})"
STATUS_COBA_LAGI = {429, 500, 502, 503, 504}

log = logging.getLogger(__name__)


class DilarangRobots(Exception):
    """robots.txt tidak mengizinkan URL ini."""


class Pengambil:
    def __init__(
        self,
        jeda: float = 1.0,
        percobaan: int = 3,
        folder_cache: Path | None = None,
        klien: httpx.Client | None = None,
        tidur=time.sleep,
        jam=time.monotonic,
    ):
        self.klien = klien or httpx.Client(
            headers={"User-Agent": USER_AGENT},
            timeout=httpx.Timeout(10.0, connect=5.0),
            follow_redirects=True,
        )
        self.jeda = jeda
        self.percobaan = percobaan
        self.folder_cache = folder_cache
        self.tidur = tidur
        self.jam = jam
        self.robots: dict[str, RobotFileParser] = {}
        self.terakhir = float("-inf")

    def _robots(self, url: str) -> RobotFileParser:
        akar = urljoin(url, "/")
        if akar not in self.robots:
            rp = RobotFileParser()
            jawab = self._get(urljoin(akar, "robots.txt"), cek_status=False)
            if jawab.status_code == 200:
                rp.parse(jawab.text.splitlines())
            elif jawab.status_code >= 500:
                rp.disallow_all = True  # server bermasalah: anggap semua dilarang
            else:
                rp.parse([])  # 404 dan sejenisnya: tidak ada aturan, semua boleh
            tunda = rp.crawl_delay(USER_AGENT)
            if tunda and float(tunda) > self.jeda:
                self.jeda = float(tunda)
            self.robots[akar] = rp
        return self.robots[akar]

    def _tunggu_giliran(self) -> None:
        sisa = self.terakhir + self.jeda - self.jam()
        if sisa > 0:
            self.tidur(sisa)
        self.terakhir = self.jam()

    def _get(self, url: str, cek_status: bool = True) -> httpx.Response:
        for ke in range(1, self.percobaan + 1):
            self._tunggu_giliran()
            tunggu = 2 ** (ke - 1)  # 1, 2, 4, ... detik
            try:
                jawab = self.klien.get(url)
            except httpx.TransportError as galat:  # timeout, koneksi putus, DNS gagal
                if ke == self.percobaan:
                    raise
                alasan = type(galat).__name__
            else:
                if jawab.status_code not in STATUS_COBA_LAGI or ke == self.percobaan:
                    if cek_status:
                        jawab.raise_for_status()
                    return jawab
                alasan = f"status {jawab.status_code}"
                if jawab.headers.get("Retry-After", "").isdigit():
                    tunggu = max(tunggu, int(jawab.headers["Retry-After"]))
            data = {"url": url, "alasan": alasan, "tunggu": tunggu}
            log.warning("coba_lagi", extra={"data": data})
            self.tidur(tunggu)
        raise RuntimeError("percobaan harus >= 1")

    def ambil(self, url: str) -> str:
        """HTML dari url. Pakai cache kalau ada (hanya untuk pengembangan)."""
        berkas = None
        if self.folder_cache:
            berkas = self.folder_cache / (hashlib.sha256(url.encode()).hexdigest()[:20] + ".html")
            if berkas.exists():
                return berkas.read_text(encoding="utf-8")
        if not self._robots(url).can_fetch(USER_AGENT, url):
            raise DilarangRobots(url)
        html = self._get(url).text
        if berkas:
            berkas.parent.mkdir(parents=True, exist_ok=True)
            berkas.write_text(html, encoding="utf-8")
        return html

