from decimal import Decimal

import pytest

from scraper_buku.parser import parse_buku, parse_daftar, parse_harga, parse_stok

KATALOG_1 = "https://books.toscrape.com/catalogue/page-1.html"
DETAIL = "https://books.toscrape.com/catalogue/a-light-in-the-attic_1000/index.html"


@pytest.mark.parametrize(
    "teks, hasil",
    [("£51.77", "51.77"), ("Â£51.77", "51.77"), (" £0.00 ", "0.00"), ("£1,234.50", "1234.50")],
)
def test_parse_harga(teks, hasil):
    assert parse_harga(teks) == Decimal(hasil)


def test_parse_harga_bukan_angka():
    with pytest.raises(ValueError, match="Harga tidak dikenali"):
        parse_harga("gratis")


@pytest.mark.parametrize(
    "teks, hasil",
    [("In stock (22 available)", 22), ("In stock (1 available)", 1), ("Out of stock", 0)],
)
def test_parse_stok(teks, hasil):
    assert parse_stok(teks) == hasil


def test_halaman_pertama(html):
    tautan, berikut = parse_daftar(html("katalog-1"), KATALOG_1)
    assert len(tautan) == 20
    assert tautan[0] == DETAIL
    assert berikut == "https://books.toscrape.com/catalogue/page-2.html"


def test_halaman_terakhir_tanpa_next(html):
    tautan, berikut = parse_daftar(html("katalog-50"), KATALOG_1.replace("1", "50"))
    assert len(tautan) == 20
    assert berikut is None


def test_detail_buku(html):
    buku = parse_buku(html("buku-light-attic"), DETAIL)
    assert buku == {
        "upc": "a897fe39b1053632",
        "judul": "A Light in the Attic",
        "harga": Decimal("51.77"),
        "stok": 22,
        "rating": 3,
        "kategori": "Poetry",
        "url": DETAIL,
    }


def test_bukan_halaman_buku(html):
    with pytest.raises(ValueError, match="Bukan halaman buku"):
        parse_buku(html("katalog-1"), KATALOG_1)

import csv
import json

from scraper_buku import atur_log, buat_parser, jelajah, main, perintah_crawl

KATALOG_1 = "https://books.toscrape.com/catalogue/page-1.html"
DETAIL = "https://books.toscrape.com/catalogue/a-light-in-the-attic_1000/index.html"


def situs_palsu(html):
    """Pengganti Pengambil.ambil: katalog dari fixture, setiap detail memakai fixture yang sama
    tapi UPC-nya dibuat unik dari URL supaya 20 buku tidak saling menimpa."""
    katalog = html("katalog-50")  # tidak punya tombol next: hanya satu halaman
    detail = html("buku-light-attic")

    def ambil(url):
        if url == KATALOG_1:
            return katalog
        return detail.replace("a897fe39b1053632", url.split("/")[-2])

    return ambil


def jalankan_crawl(tmp_path, html, ambil=None):
    args = buat_parser().parse_args(["--db", str(tmp_path / "buku.db"), "crawl"])
    atur_log("INFO")
    return perintah_crawl(args, ambil=ambil or situs_palsu(html))


def test_jelajah_berhenti_di_batas_halaman(html):
    ambil = situs_palsu(html)
    assert len(list(jelajah(ambil, KATALOG_1, maks_halaman=1))) == 20
    assert list(jelajah(ambil, KATALOG_1, maks_halaman=0)) == []


def test_crawl_dua_kali_mendeteksi_perubahan_harga(tmp_path, html, capsys):
    assert jalankan_crawl(tmp_path, html) == 0
    asli = situs_palsu(html)

    def harga_turun(url):
        return asli(url).replace("£51.77", "£40.00")

    assert jalankan_crawl(tmp_path, html, ambil=harga_turun) == 0
    log = [json.loads(b) for b in capsys.readouterr().err.splitlines()]
    berubah = [b for b in log if b["kejadian"] == "harga_berubah"]
    assert len(berubah) == 20
    assert berubah[0]["lama"] == "51.77" and berubah[0]["baru"] == "40.00"
    assert log[-1] == {**log[-1], "kejadian": "selesai", "berubah": 20}


def test_buku_gagal_dicatat_dan_kode_keluar_1(tmp_path, html, capsys):
    asli = situs_palsu(html)

    def kadang_rusak(url):
        return "<html>rusak</html>" if "frankenstein" in url else asli(url)

    assert jalankan_crawl(tmp_path, html, ambil=kadang_rusak) == 1
    log = [json.loads(b) for b in capsys.readouterr().err.splitlines()]
    assert [b["url"] for b in log if b["kejadian"] == "buku_gagal"] == [
        "https://books.toscrape.com/catalogue/frankenstein_20/index.html"
    ]
    assert log[-1]["baru"] == 19 and log[-1]["gagal"] == 1


def test_laporan_csv_dan_grafik(tmp_path, html):
    jalankan_crawl(tmp_path, html)
    keluar = tmp_path / "laporan"
    assert main(["--db", str(tmp_path / "buku.db"), "laporan", "--keluar", str(keluar)]) == 0
    with (keluar / "buku.csv").open(encoding="utf-8") as f:
        baris = list(csv.DictReader(f))
    assert len(baris) == 20
    assert baris[0]["harga_gbp"] == "51.77"
    assert (keluar / "harga-per-kategori.png").read_bytes()[:4] == b"\x89PNG"


def test_jeda_terlalu_kecil_ditolak(capsys):
    try:
        main(["crawl", "--jeda", "0.1"])
    except SystemExit as keluar:
        assert "minimal 0.5" in str(keluar.code)
    else:
        raise AssertionError("harus berhenti")
